function validateLiq() {
    //debugger;
    mandatory(tw.local.odcRequest.ContractLiquidation.liqAmount, "tw.local.odcRequest.ContractLiquidation.liqAmount");
    mandatory(tw.local.odcRequest.ContractLiquidation.creditValueDate, "tw.local.odcRequest.ContractLiquidation.creditValueDate");
    mandatory(tw.local.odcRequest.ContractLiquidation.debitValueDate, "tw.local.odcRequest.ContractLiquidation.debitValueDate");
    
    checkDate(tw.local.odcRequest.ContractLiquidation.creditValueDate, tw.local.odcRequest.requestDate, "tw.local.odcRequest.ContractLiquidation.creditValueDate", "Invalid date", "Credit Value Date should not be less than request date");
    checkDate(tw.local.odcRequest.ContractLiquidation.debitValueDate, tw.local.odcRequest.requestDate, "tw.local.odcRequest.ContractLiquidation.debitValueDate", "Invalid date", "Debit Value Date should not be less than request date");
    mandatory(tw.local.odcRequest.ContractLiquidation.creditedAccount.accountClass.value, "tw.local.odcRequest.ContractLiquidation.creditedAccount.accountClass");
    mandatory(tw.local.odcRequest.ContractLiquidation.debitedAccountNo, "tw.local.odcRequest.ContractLiquidation.debitedAccountNo");

    if (tw.local.odcRequest.ContractLiquidation.creditedAccount.accountClass.value == "GL Account") {
        mandatory(tw.local.odcRequest.ContractLiquidation.creditedAccount.glAccountNo, "tw.local.odcRequest.ContractLiquidation.creditedAccount.glAccountNo");

        if (!!tw.local.odcRequest.ContractLiquidation.creditedAccount.glAccountNo && tw.local.glAccountVerified == false) {
            tw.local.errorMessage += "<li>" + "GL Account is not verified." + "</li>";
            tw.system.coachValidation.addValidationError(tw.local.odcRequest.ContractLiquidation.creditedAccount.glAccountNo, "GL Account is not verified.");
        }

        //debugger;
        if (!!tw.local.odcRequest.ContractLiquidation.creditedAccount.glAccountNo && tw.local.glAccountVerified) {
            mandatory(tw.local.odcRequest.ContractLiquidation.creditedAccount.branchCode, "tw.local.odcRequest.ContractLiquidation.creditedAccount.branchCode");
            mandatory(tw.local.odcRequest.ContractLiquidation.creditedAccount.currency.value, "tw.local.odcRequest.ContractLiquidation.creditedAccount.currency");
        }

        //Validate OverDraft
        if (tw.local.odcRequest.ContractLiquidation.creditedAmount.amountInAccount > tw.local.odcRequest.ContractLiquidation.creditedAccount.balance && tw.local.odcRequest.ContractLiquidation.creditedAccount.isOverDraft) {
            addError("tw.local.odcRequest.ContractLiquidation.creditedAmount.amountInAccount", "ERROR: Must be <= Account Balance")
        }
    
    } else {
        mandatory(tw.local.odcRequest.ContractLiquidation.creditedAccount.customerAccountNo, "tw.local.odcRequest.ContractLiquidation.creditedAccount.customerAccountNo");
    }

    if (tw.local.odcRequest.ContractLiquidation.liqAmount > tw.local.odcRequest.FinancialDetailsFO.outstandingAmount) {
        addError("tw.local.odcRequest.ContractLiquidation.liqAmount", "Liquidation Amount must be <= ODC Outstanding Amount");
        tw.local.errorMessage += "<li>" + "Liquidation Amount must be less than or equal to ODC Outstanding Amount." + "</li>";
    }

    //----------------------------------------------- Charges and Commissions VALIDATION -------------------------------------		
    for (var i = 0; i < tw.local.odcRequest.ChargesAndCommissions.length; i++) {

        //Description - Flat Amount
        if (tw.local.odcRequest.ChargesAndCommissions[i].rateType == "Flat Amount") {
            if (tw.local.odcRequest.ChargesAndCommissions[i].changeAmount < 0 || tw.local.odcRequest.ChargesAndCommissions[i].changeAmount == null) {
                addError("tw.local.odcRequest.ChargesAndCommissions[" + i + "].changeAmount", "Must be >= 0");
            } else if (tw.local.odcRequest.ChargesAndCommissions[i].changeAmount > 0) {
                validateDecimal2(tw.local.odcRequest.ChargesAndCommissions[i].changeAmount, "tw.local.odcRequest.ChargesAndCommissions[" + i + "].changeAmount", "Must be Decimal(14,2)")
            }
            //        mandatory(tw.local.odcRequest.ChargesAndCommissions[i].changeAmount, "tw.local.odcRequest.ChargesAndCommissions[" + i + "].changeAmount");

            // minLength(tw.local.odcRequest.ChargesAndCommissions[i].changeAmount, "tw.local.odcRequest.ChargesAndCommissions[" + i + "].changeAmount", 2, "Shouldn't be less than 2 character", "Change Amount: Shouldn't be less than 2 character");
            // maxLength(tw.local.odcRequest.ChargesAndCommissions[i].changeAmount, "tw.local.odcRequest.ChargesAndCommissions[" + i + "].changeAmount", 14, "Shouldn't be more than 14 character", "Change Amount:" + "Shouldn't be more than 14 character");

        //Fixed Rate
        } else {

            if (tw.local.odcRequest.ChargesAndCommissions[i].changePercentage < 0 || tw.local.odcRequest.ChargesAndCommissions[i].changePercentage == null) {
                addError("tw.local.odcRequest.ChargesAndCommissions[" + i + "].changePercentage", "Must be >= 0");
            } else if (tw.local.odcRequest.ChargesAndCommissions[i].changePercentage > 0) {
                validateDecimal2(tw.local.odcRequest.ChargesAndCommissions[i].changePercentage, "tw.local.odcRequest.ChargesAndCommissions[" + i + "].changePercentage", "Must be Decimal(14,2)")
            }
            // minLength(tw.local.odcRequest.ChargesAndCommissions[i].changePercentage, "tw.local.odcRequest.ChargesAndCommissions[" + i + "].changePercentage", 2, "Shouldn't be less than 2 character", "Change Percentage: Shouldn't be less than 2 character");
            // maxLength(tw.local.odcRequest.ChargesAndCommissions[i].changePercentage, "tw.local.odcRequest.ChargesAndCommissions[" + i + "].changePercentage", 14, "Shouldn't be more than 14 character", "Change Percentage:" + "Shouldn't be more than 14 character");
        }

        //skip validation if waiver or changeAmnt < 0
        if (tw.local.odcRequest.ChargesAndCommissions[i].waiver == false && tw.local.odcRequest.ChargesAndCommissions[i].changeAmount > 0) {

            //Validate debited accounts
            // mandatory(tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.customerAccountNo, "tw.local.odcRequest.ChargesAndCommissions[" + i + "].debitedAccount.customerAccountNo");
            // mandatory(tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.accountClass.value, "tw.local.odcRequest.ChargesAndCommissions[" + i + "].debitedAccount.accountClass");

            //GL Account
            if (tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.accountClass.value == "GL Account") {

                if (tw.local.odcRequest.ChargesAndCommissions[i].isGLFound == false) {
                    addError("tw.local.odcRequest.ChargesAndCommissions[" + i + "].debitedAccount.glAccountNo", "GL Account Not Verified");
                }

                mandatory(tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.glAccountNo, "tw.local.odcRequest.ChargesAndCommissions[" + i + "].debitedAccount.glAccountNo");
                mandatory(tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.currency.value, "tw.local.odcRequest.ChargesAndCommissions[" + i + "].debitedAccount.currency.value");
                mandatory(tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.branchCode, "tw.local.odcRequest.ChargesAndCommissions[" + i + "].debitedAccount.branchCode");

                //Customer Account
            } else {
                mandatory(tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.customerAccountNo, "tw.local.odcRequest.ChargesAndCommissions[" + i + "].debitedAccount.customerAccountNo");
            }

            //DebitedAmount

            if (tw.local.odcRequest.ChargesAndCommissions[i].debitedAmount.negotiatedExRate > 0) {
                validateDecimal(tw.local.odcRequest.ChargesAndCommissions[i].debitedAmount.negotiatedExRate, "tw.local.odcRequest.ChargesAndCommissions[" + i + "].debitedAmount.negotiatedExRate", "Must be Decimal(16,10)")
            }

            // minLength(tw.local.odcRequest.ChargesAndCommissions[i].debitedAmount.negotiatedExRate, "tw.local.odcRequest.ChargesAndCommissions[" + i + "].debitedAmount.negotiatedExRate", 2, "Shouldn't be less than 2 character", "Negotiated Exchange Rate: Shouldn't be less than 2 character");
            // maxLength(tw.local.odcRequest.ChargesAndCommissions[i].debitedAmount.negotiatedExRate, "tw.local.odcRequest.ChargesAndCommissions[" + i + "].debitedAmount.negotiatedExRate", 14, "Shouldn't be more than 14 character", "Negotiated Exchange Rate:" + "Shouldn't be more than 14 character");

            //Correct Validation but Waiting confirmation on what to do if GL account
            if ((tw.local.odcRequest.ChargesAndCommissions[i].debitedAmount.amountInAccount >
                tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.balance) && tw.local.odcRequest.ChargesAndCommissions[i].debitedAccount.isOverDraft == false) {
                addError("tw.local.odcRequest.ChargesAndCommissions[" + i + "].debitedAmount.amountInAccount", "ERROR: Must be <= Account Balance");
            }
        }
    }
}   //end of validation function

