//calculate credited amount in cuurency
this.setAmountInCurrency = function(){
	var liqAmount  =  this.ui.get("LiquidationAmount").getData()? this.ui.get("LiquidationAmount").getData():0;
	var negoExRate =  this.ui.get("negotiatedExRate").getData()? this.ui.get("negotiatedExRate").getData():0;
	
	if( liqAmount > 0   &&   negoExRate > 0 )
		this.ui.get("creditedAmountinAccCurrency").setData(liqAmount * negoExRate);
}

//validate overDraft
this.validateOverDraft = function () {
	var AccBalance          =  this.ui.get("AccountBalance").getData()? this.ui.get("AccountBalance").getData() : 0;
	var amountinAccCurrency =  this.ui.get("creditedAmountinAccCurrency").getData()? this.ui.get("creditedAmountinAccCurrency").getData() : 0;
	var overDraft           =  this.context.binding.get("value").get("ContractLiquidation").get("creditedAccount").get("isOverDraft");
	
	if(amountinAccCurrency > AccBalance){
		if (overDraft) 
			{
			
			this.ui.get( "creditedAmountinAccCurrency").setValid(false,"WARNING: Amount in account currency should be less than Account Balance");
			}
		else{
			this.ui.get( "creditedAmountinAccCurrency").setValid(false,"ERROR: Amount in Account Currency > Account Balance and Account Type is not Overdraft");
			}
	
	}else{
		this.ui.get( "creditedAmountinAccCurrency").setValid(true);
	}//end of if
	
}

