//---------------------------------------Validation Library------------------------------------
/* Add a coach validation error 		
EX: addError(tw.local.name , 'validation message!')*/
var validationList = [];
this.addError = function (path, message) {
	if (validationList == null) {
		validationList = [];
	}
	validationList.push({
		errorBOPath: path,
		errorMessage: message,
	});
	// return validationList;
};

/* Add a coach validation error if the field is null 'Mandatory', 
   message is OPTIONAL!! , DEFAULT is 'This Field Is Mandatory',
   EX: mandatory(tw.local.name , 'tw.local.name', 'validation message') */

this.mandatory = function (value, path, message) {
	if (!message) {
		message = "This Field Is Mandatory";
	}

	if (value == null) {
		this.addError(path, message);
		return false;
	} else {
		switch (typeof value) {
			case "string":
				if (value.trim().length == 0) {
					this.addError(path, message);
					return false;
				}
				break;
			case "number":
				if (value == 0.0 || value < 0.0) {
					this.addError(path, message);
					return false;
				}
				break;
		}
	}
	return true;
};

this.mandatoryList = function (mandatoryList) {
	mandatoryList.forEach((element) => {
		this.mandatory(element[0], element[1], element[2]);
	});
};

/* Add a coach validation error if the date is in the past and the last variable is OPTIONAL to exclude today.
   EX: notPastDate(tw.local.date , 'tw.local.date' , 'validation message!' , false)*/
this.notPastDate = function (value, path, message, exclude) {
	if (!value) return;

	var checkDate = this.getMidNightDate();
	if (exclude) {
		if (value != null && value < checkDate) {
			this.addError(path, message);
			return false;
		}
		return true;
	} else {
		if (value != null && value <= new Date()) {
			this.addError(path, message);
			return false;
		}
		return true;
	}
};

/* Add a coach validation error if the date is between two dates.
   EX: dateBetween(tw.local.date,'tw.local.date', date1 , date2,'validation message!')*/
this.dateBetween = function (value, path, date1, date2, message) {
	if (value && value > date1 && value < date2) {
		return true;
	}

	this.addError(path, message);
	return false;
};

/* Add a coach validation error if the date is in the future and the last variable is OPTIONAL to exclude today.
  EX:	notFutureDate(tw.local.date, 'tw.local.date', 'validation message!' , false)*/
this.notFutureDate = function (value, path, message, exclude) {
	if (!value) return;
	var checkDate = this.getMidNightDate();
	if (exclude && exclude === true) {
		if (value != null && value > checkDate) {
			this.addError(path, message);
			return false;
		}
		return true;
	} else {
		if (value != null && value >= new Date()) {
			this.addError(path, message);
			return false;
		}
		return true;
	}
};

/* Add a coach validation error if the STRING length is greater than given length (len).
  EX:	maxLength(tw.local.name , 'tw.local.name' , 14 ,'validation message!')*/
this.maxLength = function (value, path, len, message) {
	if (value && value.length > len) {
		this.addError(path, message);
		return false;
	}
	return true;
};

/* Add a coach validation error if the STRING length is less than given length (len).
   EX: minLength(tw.local.name , 'tw.local.name', 10, 'validation message!')*/
this.minLength = function (value, path, len, message) {
	if (value && value.length < len) {
		this.addError(path, message);
		return false;
	}
	return true;
};

this.exactLength = function (value, path, len, message) {
	if (value && value.length != len) {
		this.addError(path, message);
		return false;
	}
	return true;
};

/* Add a coach validation error if the number is greater than given value (max).
 * EX: maxNumber(tw.local.name , 'tw.local.name' , 14 ,'validation message!')*/
this.maxNumber = function (value, path, max, message) {
	if (value && value > max) {
		this.addError(path, message);
		return false;
	}
	return true;
};

/* Add a coach validation error if the number is less than given value (min).
   EX: minNumber(tw.local.name , 'tw.local.name' , 14 , 'validation message!')*/
this.minNumber = function (value, path, min, message) {
	if (value && value < min) {
		this.addError(path, message);
		return false;
	}
	return true;
};

/* Validates the before and after decimal length (even if string).
   message is OPTIONAL , DEFAULT `Max is (${beforeDecimal}) before decimal and (${afterDecimal}) after it` 
   Ex: validateDecimal (tw.local.decimal, 'tw.local.decimal', 10, 6, 'validation message')*/
this.validateDecimal = function (value, path, beforeDecimal, afterDecimal, message) {
	if (!value) return;
	if (!message || message == "") {
		message = `Max is (${beforeDecimal}) before decimal and (${afterDecimal}) after it`;
	}
	// Handle string or number input
	if (typeof value === "number") {
		value = value.toString();
	}
	// Regex to check overall format
	const regex = new RegExp("^\\d{1," + beforeDecimal + "}\\.?\\d{0," + afterDecimal + "}$");

	if (regex.test(value) == false) {
		this.addError(path, message);
		return false;
	}
	return true;
};

