/* Style for the red circle counter */
.red-circle {
	position: absolute;
	top: 0;
	right: 0;
	width: 17px;
	height: 17px;
	background-color: red;
	border-radius: 50%;
	display: flex;
	justify-content: center;
	align-items: center;
	color: white;
	font-weight: bold;
}

.tab-link {
	font-size: medium;
}

/* Style for the tab list */
.tab-list {
	list-style-type: none;
	padding: 0;
	margin: 0; /* Remove default margin */
}

/* Style for each tab item */
.tab-item {
	margin-bottom: 5px; /* Reduce space between tabs */
	border: none;
	padding: 5px;
	display: flex;
	align-items: center;
	list-style: none;
}

/* Style for the tab name */
.tab-name {
	font-size: 16px;
	margin: 0;
	color: #8a1412; /* Replaced red with a shade of orange */
	text-decoration: none;
	font-weight: bold;
}

.tab-name:hover {
	text-decoration: underline;
	color: #d35400;
}

.tab-name:focus {
	text-decoration: underline;
	color: #d35400;
}

.tab-container {
	display: flex;
	flex-direction: column;
	width: 100%;
}

.tab-header {
	display: flex;
	align-items: center;
	width: 100%;
}

/* Style for the gradient box */
.gradient-box {
	flex: 1;
	padding: 10px 20px;
	background: linear-gradient(45deg, rgba(255, 255, 255, 0.8), rgba(240, 240, 240, 0.8));
	border-radius: 4px;
	display: flex;
	align-items: center;
	cursor: auto; /* Change cursor to auto to indicate non-clickable */
	transition: none;
}

/* .gradient-box:hover {
	transform: scale(1.05);
	background: linear-gradient(45deg, rgba(255, 255, 255, 1), rgba(240, 240, 240, 1));
} */

.tab {
	position: relative;
	width: 100%;
}

.tab::after {
	content: attr(error-count);
	color: red;
	font-size: 10px;
	position: absolute;
	right: 5px;
	top: 5px;
}

/* Add animation for the highlighted field */
.highlighted-field {
	animation-name: highlight;
	animation-duration: 1.5s;
}

@keyframes highlight {
	from {
		background-color: yellow;
	}
	to {
		background-color: initial;
	}
}

.error-list {
	display: none;
	margin-left: 20px;
	padding: 0;
	list-style-type: none;
	transition: max-height 0.2s ease-out;
	overflow: hidden;
}

.error-list.collapsed {
	max-height: 0;
	transition: max-height 0.3s ease-out;
}

.error-list.expanded {
	max-height: 500px; /* Adjust this value as needed */
	transition: max-height 0.3s ease-in;
}

/* Style for the toggle button */
.toggle-button {
	margin-left: 10px;
	background-color: #f7f7f7; /* Off-white background */
	color: #8a1412; /* Darker red for text */
	border: 1px solid #e0e0e0; /* Off-white border */
	border-radius: 4px;
	padding: 5px 10px;
	cursor: pointer;
	transition: background-color 0.3s ease, transform 0.3s ease;
}

.toggle-button:hover {
	background-color: #e8e8e8; /* Slightly darker off-white on hover */
	transform: scale(1.05);
}

.bullet {
	color: #ff8c00; /* Replaced red with a shade of orange */
	margin-right: 5px; /* Adjust spacing between bullet and link */
}

.message-link {
	cursor: pointer;
	color: #8a1412; /* Replaced red with a shade of orange */
	text-decoration: none;
	padding: 5px; /* Add padding for better hover area */
	transition: color 0.2s ease, background-color 0.2s ease; /* Add transition for smooth animation */
	position: relative;
}

.message-link:hover {
	text-decoration: underline;
	color: #d35400; /* Darker shade of orange on hover */
	/* background-color: rgba(255, 140, 0, 0.1); */
}

