//---------------VALIDATION FUNCTIONS---------------------------------------------------------

/* 
How to use:
    - put these functions at the inline JS of the template.
	- in the CSHS script, add the following line:
		var lib = bpmext.ui.getView('templatePathName');
	- at te start of the script, add the following line, to clear the error list:
		lib.setErrorList();
	- use the functions as follows:
		lib.addError(path, message);
		lib.mandatory(value, path, message);
	- at the end of the script, add the following line, to get the error list:
		lib.getErrorList();
*/

var dateOptions = { day: "numeric", month: "long", year: "numeric" };
var validationList = [];

/* Add a coach validation error if the field is empty, message is OPTIONAL!!
mandatory(tw.local.input, "tw.local.input", message : concat) : CSHS */
this.mandatory = function (value, path, message) {

	message = message || 'This field is Mandatory';

	if (value == null || value == undefined) {
		addError(path, message);
		return false;
	} else {
		switch (typeof value) {
			case "string":
				if (value.trim().length == 0) {
					addError(path, message);
					return false;
				}
				break;
			case "number":
				if (value == 0.0 || value < 0.0) {
					addError(path, message);
					return false;
				}
				break;
		}
	}
	return true;
};

/* Add a coach validation error 		
EX: addError(tw.local.name , 'validation message!')*/
function addError (path, message) {
	
	if (validationList == null) {
		validationList = [];
	}
	validationList.push({
		errorBOPath: path,
		errorMessage: message,
	});
};

/* Add a coach validation error if the date is in the past today.
   EX: notPastDate(tw.local.date , 'tw.local.date' , 'validation message!' , false)*/
this.notPastDate = function (value, path, exclude, message) {
	if (!value) return;
	message = message || "Please input a valid future date";

	var checkDate = this.getMidNightDate();
	//exclude today?
	if (exclude && value < checkDate) {
		this.addError(path, message);
		return false;
	}
	if (!exclude && value <= new Date()) {
		this.addError(path, message);
		return false;
	}
	return true;
};

/* Add a coach validation error if the date is between two dates.
   EX: dateBetween(tw.local.date,'tw.local.date', date1 , date2,'validation message!')*/
this.dateBetween = function (value, path, date1, date2, message) {
	if (!value) return;

	message =
		message ||
		`This date must be between ${date1.toLocaleDateString(
			"en-GB",
			dateOptions
		)} and ${date2.toLocaleDateString("en-GB", dateOptions)}`;

	if (value && value > date1 && value < date2) {
		return true;
	}

	this.addError(path, message);
	return false;
};

/* Add a coach validation error if the date is in the future and the last variable is OPTIONAL to exclude today.
  EX:	notFutureDate(tw.local.date, 'tw.local.date', 'validation message!' , false)*/
this.notFutureDate = function (value, path, exclude, message) {
	if (!value) return;
	
	message = message || "Please input a valid date in the past";

	var checkDate = this.getMidNightDate();
	//exclude today?
	if (exclude && value > checkDate) {
		this.addError(path, message);
		return false;
	}
	if (!exclude && value >= new Date()) {
		this.addError(path, message);
		return false;
	}

	return true;
};

/* Add a coach validation error if the STRING length is greater than given length (len).
  EX:	maxLength(tw.local.name , 'tw.local.name' , 14 ,'validation message!')*/
this.maxLength = function (value, path, len, message) {
	if (!value) return;
	message = message || `This field can only contain up to ${len} characters.`;
	if (value.length > len) {
		this.addError(path, message);
		return false;
	}
	return true;
};

/* Add a coach validation error if the STRING length is less than given length (len).
   EX: minLength(tw.local.name , 'tw.local.name', 10, 'validation message!')*/
this.minLength = function (value, path, len, message) {
	if (!value) return;

	message = message || `This field must contain at least ${len} characters.`;
	if (value.length < len) {
		this.addError(path, message);
		return false;
	}
	return true;
};

/* Add a coach validation error if the number is greater than given value (max).
 * EX: maxNumber(tw.local.name , 'tw.local.name' , 14 ,'validation message!')*/
this.maxNumber = function (value, path, max, message) {
	if (!value) return;
	
	message = message || `This value must be < ${max}`;
	if (!isNaN(value) && value > max) {
		this.addError(path, message);
		return false;
	}
	return true;
};

/* Add a coach validation error if the number is less than given value (min).
   EX: minNumber(tw.local.name , 'tw.local.name' , 14 , 'validation message!')*/
this.minNumber = function (value, path, min, message) {
	if (!value) return;
	
	message = message || `This value must be > ${min}`;
	if (!isNaN(value) && value < min) {
		this.addError(path, message);
		return false;
	}
	return true;
};

// FOR VIEW
//prevents input length exceeding len, only works for string and on input event
this.maxLenOnInput = function (me, potential, len, message) {
	if (potential.length > len) {
		var label = me.getLabel();
		message = message || `${label} can only contain up to ${len} characters.`;
		me.setValid(false, message);
		return false;
	}
	me.setValid(true);
	return true;
};

this.isChecker = function (fun, me, ...args) {
	if (!me) return;
	if (me.getVisibility() == "READONLY" || me.getVisibility() == "HIDDEN") {
		return;
	}
	return fun(...args);
};
