var isAmndFinal = false;
var length = 0;
this.setColumnsVis = function () {
	var vis = "V";
	if ((this.context.options.requestType.get("value") == "IDC Amendment" || this.context.options.requestType.get("value") == "IDC Completion") && !this.context.options.isChecker.get("value")) {
        this.context.options.addParty.set("value", false);
        this.context.options.deleteParty.set("value", false);
        if (this.context.options.requestState.get("value") == "Initial"){
            vis = "R";
            isAmndFinal = false;
        }else if (this.context.options.requestState.get("value") == "Final"){
        	vis = "R";
            length = this.context.binding.get("value").length();
            if (length < 5) {
                this.context.options.addParty.set("value", true);
                isAmndFinal = true;
            }    
        }
    }else{
        vis = "V";
        this.context.options.addParty.set("value", true);
        this.context.options.deleteParty.set("value", true);
        isAmndFinal = false;
    }

    var columns = [];
    columns = [
    {renderAs: "V", visibility: vis},
    {renderAs: "V", visibility: vis},
    {renderAs: "V", visibility: vis},
    {renderAs: "V", visibility: "V"},
    {renderAs: "V", visibility: vis},
    {renderAs: "V", visibility: "V"},
    {renderAs: "V", visibility: "V"},
    {renderAs: "V", visibility: "V"},
    {renderAs: "V", visibility: "V"},
    {renderAs: "V", visibility: "V"},
    {renderAs: "V", visibility: "V"},
    {renderAs: "V", visibility: "V"},
    {renderAs: "V", visibility: "V"},
    {renderAs: "V", visibility: "V"}
    ];
    this.context.options.columns.set("value", []);
    this.context.options.columns.set("value", columns);
}

