		alert("You can not delete this row");
		return false;
	}else{
		this.context.options.addParty.set("value", true);

		this.context.options.deletedCIF.set("value", value2.partyId);
		if (type == "Accountee" || type == "Drawee") {
        		this.ui.get("update").click();
		}
		return true;
	}
}


