this.validateOneType = function (type,value) {
	var record = value.ui.getIndex();
	var n = 0;
	for (var i=0; i< this.context.binding.get("value").length(); i++) {
		if(this.context.binding.get("value").get(i).get("partyType").get("name") == type){
			n+=1
		}
	}
	if(value.getData().name == type && n>1){
		this.context.options.warningMess.set("value", "Only one  is allowed of same Type");
		this.context.binding.get("value").remove(record);
	}else{
		this.context.options.warningMess.set("value", "");
	}
}

