			this.context.options.draweeCIF.set("value", this.context.binding.get("value").get(i).get("CIF"));
		}
		if(this.context.binding.get("value").get(i).get("partyType").get("name") == "Case in Need"){
			this.context.options.caseCIF.set("value", this.context.binding.get("value").get(i).get("CIF"));
