}
this.setPartyId = function (value){
	var record = value.ui.getIndex();
	var type = this.context.binding.get("value").get(record).get("partyType").get("name");
	this.context.binding.get("value").get(record).set("isRetrived", false);
	
	//Set Owner CIF
//	this.setOwnerCIF();
	//Validation
	if(isNaN(Number(value.getData())) || value.getData().length < 8){
        value.setValid(false , "must be 8 digits");
		return false;
	}else{
        value.setValid(true);
        if (type == "Accountee" || type == "Drawee") {
        	this.ui.get("update").click();
        }
		return true;	
	}
}

this.concatOnDelete = function (value){
	var newString = "";
	for (var i=0; i<this.context.binding.get("value").length(); i++) {
		if (i == value && i > 1) {
			continue;
		}
		newString +=this.context.binding.get("value").get(i).get("partyType").name +",";
	}
	this.context.options.concatString.set("value", newString);
}

