this.mapPartyData = function (){
      record = this.context.options.partyIndex.get("value");
	if(this.context.binding.get("value").get(record).get("partyType").get("value") == "Remitting Bank" && this.context.options.customerFullDetails.get("value").get("customerType") != "B"){

		this.ui.get("PartyTable/partyCIF["+record+"]").setValid(false,"This CIF is not corresponding to a Bank");
	}else{	
		this.context.binding.get("value").get(record).set("partyId",  this.context.binding.get("value").get(record).get("partyCIF"));
		this.context.binding.get("value").get(record).set("address1", this.context.options.customerFullDetails.get("value").get("customerAddress").get("addressLine1"));
		this.context.binding.get("value").get(record).set("address2", this.context.options.customerFullDetails.get("value").get("customerAddress").get("addressLine2"));
		this.context.binding.get("value").get(record).set("address3", this.context.options.customerFullDetails.get("value").get("customerAddress").get("addressLine3"));
		this.context.binding.get("value").get(record).set("name", this.context.options.customerFullDetails.get("value").get("EnglishName"));
		if (this.context.options.customerFullDetails.get("value").get("nationality") == "" || this.context.options.customerFullDetails.get("value").get("nationality") == null || this.context.options.customerFullDetails.get("value").get("nationality") == undefined ) {
			this.context.binding.get("value").get(record).set("country","EG");
		}
		else{
			this.context.binding.get("value").get(record).set("country",this.context.options.customerFullDetails.get("value").get("nationality"));
		}
		if (this.context.options.customerFullDetails.get("value").get("language") == "" || this.context.options.customerFullDetails.get("value").get("language") == null || this.context.options.customerFullDetails.get("value").get("language") == undefined ) {
			this.context.binding.get("value").get(record).set("language", "ENG");
		}else{
			this.context.binding.get("value").get(record).set("language", this.context.options.customerFullDetails.get("value").get("language"));
		}
		this.context.binding.get("value").get(record).set("branch", {});
		this.context.binding.get("value").get(record).get("branch").set("value", this.context.options.customerFullDetails.get("value").get("customerBranch"));
		this.context.binding.get("value").get(record).get("branch").set("name", this.context.options.customerFullDetails.get("value").get("customerBranch"));
		if(this.context.binding.get("value").get(record).get("partyType").get("value") === "Remitting Bank"){	
			
			var appID = this.context.options.appID.get("value");
			var cif = this.context.binding.get("value").get(record).get("partyCIF");
			var input = cif+"-"+appID;
			this.ui.get("GetAddressBIC").execute(input);
			if (!!this.context.options.BeneficiaryDetails.get("value").get("correspondentRefNum")) {	
				
				this.context.binding.get("value").get(record).set("reference", this.context.options.BeneficiaryDetails.get("value").get("correspondentRefNum"));
			}else{
				this.context.binding.get("value").get(record).set("reference","NO REF");
			}
			
			this.ui.get("PartyTable/address["+record+"]").setEnabled(true);
			this.ui.get("PartyTable/media["+record+"]").setEnabled(true);
		}else{	
			this.context.binding.get("value").get(record).set("reference", "NO REF");
			this.ui.get("PartyTable/address["+record+"]").hide();
			this.ui.get("PartyTable/media["+record+"]").hide();
		}
	}
}

